<script setup lang="ts">
import {readDraft,writeDraft,clearDraft,protectUnload} from '../lib/edit-protection';
import {confirmAction} from '../lib/dialog';import {onBeforeRouteLeave} from 'vue-router';
import DateTimePicker from '../components/DateTimePicker.vue';
import { ref,onMounted,watch,computed } from 'vue';import { api,catalog,loadCatalog } from '../lib/api';import type { Event } from '../../shared/models';
const data=ref<{events:Event[];mail_provider:string}|null>(null),error=ref(''),notice=ref(''),selected=ref(''),busy=ref(false);
const event=ref({name:'',year:new Date().getFullYear(),timezone:'Asia/Shanghai',opens_at:'',closes_at:'',submissions_open:false,wishes_open:true,active:true});
async function load(){data.value=await api('/api/admin/settings');await loadCatalog();}
function selectEvent(id:string){selected.value=id;const e=data.value?.events.find(x=>x.id===id);eventVersion.value=e?.version??null;event.value=e?{name:e.name,year:e.year,timezone:e.timezone,opens_at:e.opens_at??'',closes_at:e.closes_at??'',submissions_open:!!e.submissions_open,wishes_open:!!e.wishes_open,active:!!e.active}:{name:'',year:new Date().getFullYear(),timezone:'Asia/Shanghai',opens_at:'',closes_at:'',submissions_open:false,wishes_open:true,active:true};}
async function saveEvent(){if(busy.value)return;busy.value=true;error.value='';try{const value={...event.value,opens_at:event.value.opens_at?new Date(event.value.opens_at).toISOString():null,closes_at:event.value.closes_at?new Date(event.value.closes_at).toISOString():null};if(selected.value)await api('/api/admin/events/'+selected.value,{...value,expectedVersion:eventVersion.value},'PUT');else{const r=await api<{id:string}>('/api/admin/events',value);selected.value=r.id;}await load();selectEvent(selected.value);eventBase.value=JSON.stringify(event.value);persist();notice.value='活动已保存';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
const eventBase=ref(''),eventVersion=ref<number|null>(null);let ready=false;
const eventDirty=computed(()=>!!eventBase.value&&JSON.stringify(event.value)!==eventBase.value);
const dirty=computed(()=>eventDirty.value);
function persist(){if(!ready)return;if(dirty.value){if(!writeDraft('settings',{selected:selected.value,event:event.value,eventVersion:eventVersion.value}))notice.value='本机备份不可用，请保存后再离开。';}else clearDraft('settings');}
watch(event,persist,{deep:true,flush:'sync'});
async function pick(id:string){if(busy.value)return;if(eventDirty.value&&!await confirmAction('切换活动将放弃尚未保存的活动资料，确定切换？'))return;ready=false;selectEvent(id);eventBase.value=JSON.stringify(event.value);ready=true;persist();}
async function choose(e:globalThis.Event){const el=e.target as HTMLSelectElement;try{await pick(el.value);}finally{el.value=selected.value;}}
async function discard(){if(!await confirmAction('放弃本机尚未保存的设置，重新读取服务器资料？'))return;ready=false;clearDraft('settings');await load();selectEvent(selected.value);eventBase.value=JSON.stringify(event.value);ready=true;notice.value='已重新读取服务器资料。';}
onMounted(async()=>{try{await load();selectEvent(catalog.eventId);eventBase.value=JSON.stringify(event.value);const old=readDraft<{selected:string;event:typeof event.value;eventVersion?:number}>('settings');if(old&&await confirmAction('发现本机未保存的活动设置，是否恢复？')){selectEvent(old.selected);eventBase.value=JSON.stringify(event.value);if(old.eventVersion&&data.value?.events.find(e=>e.id===old.selected)?.version!==old.eventVersion)notice.value='服务器活动资料已经更新，恢复的本机内容请与当前设置核对后再保存。';else notice.value='已恢复本机未保存设置。';event.value=old.event;eventVersion.value=old.eventVersion??eventVersion.value;}else clearDraft('settings');ready=true;persist();}catch(e){error.value=(e as Error).message;}});
protectUnload(()=>dirty.value||busy.value);onBeforeRouteLeave(async()=>!busy.value&&(!dirty.value||await confirmAction('设置尚未保存，本机草稿会保留。确定离开？')));
</script>
<template><div class="page"><header class="page-head"><div><h1>活动设置</h1></div></header><p v-if="error" class="alert error" role="alert">{{ error }}</p><p v-if="notice" class="alert success" role="status">{{ notice }}</p><p v-if="dirty" class="hint" role="status">有未保存的设置 · 本机保留草稿 <button type="button" @click="discard">放弃修改</button></p><fieldset :disabled="busy||!data"><div><section class="paper"><h2>活动资料</h2><FieldLabel>选择活动<select :value="selected" @change="choose($event)"><option value="">＋ 新建活动</option><option v-for="e in data?.events" :value="e.id">{{ e.name }}</option></select></FieldLabel><form @submit.prevent="saveEvent"><FieldLabel>活动名称<input v-model="event.name" required maxlength="100"></FieldLabel><div class="grid two"><FieldLabel>年份<input v-model.number="event.year" type="number" min="2000" max="2200" required></FieldLabel><FieldLabel>时区<input v-model="event.timezone" required placeholder="Asia/Shanghai"></FieldLabel></div><DateTimePicker v-model="event.opens_at" label="征稿开始时间" :timezone="event.timezone"/><DateTimePicker v-model="event.closes_at" label="征稿结束时间" :timezone="event.timezone"/><FieldLabel class="check"><input type="checkbox" v-model="event.submissions_open">开放征稿</FieldLabel><FieldLabel class="check"><input type="checkbox" v-model="event.wishes_open">开放祝福语投稿（独立于作品征稿）</FieldLabel><FieldLabel class="check"><input type="checkbox" v-model="event.active">活动可见</FieldLabel><button class="primary" :disabled="busy">保存活动</button></form></section></div><section class="paper"><h2>邮件与访问</h2><p>当前邮件适配器：<code>{{ data?.mail_provider }}</code>。正式域名：<a href="https://usagi.mikanyan.com">usagi.mikanyan.com</a></p><p class="hint">超级管理员通过“管理员任免”管理普通管理员，不提供自助提权。邮件凭据通过 Cloudflare Secrets 设置，不在网页保存。</p></section></fieldset></div></template>
